const NOW = 1700000000; // fixed clock — no Date used
const SKEW = 300;
const POLICY = {
  algs: ["RS256", "ES256"],
  iss: "https://idp.example.com",
  aud: "orders-web",
  nonce: "n-9f3a",
};

function validate(t) {
  const h = t.header, p = t.payload;
  if (!POLICY.algs.includes(h.alg)) return "REJECT alg";
  if (!h.kid) return "REJECT kid";
  if (p.iss !== POLICY.iss) return "REJECT iss";
  if (p.aud !== POLICY.aud) return "REJECT aud";
  if (typeof p.exp !== "number" || p.exp + SKEW <= NOW) return "REJECT exp";
  if (p.nonce !== POLICY.nonce) return "REJECT nonce";
  return "ACCEPT";
}

const base = { iss: POLICY.iss, aud: POLICY.aud, exp: NOW + 3600, nonce: POLICY.nonce };
const tokens = [
  { header: { alg: "none",  kid: "k1" }, payload: { ...base } },
  { header: { alg: "HS256", kid: "k1" }, payload: { ...base } },
  { header: { alg: "RS256" },            payload: { ...base } },
  { header: { alg: "RS256", kid: "k1" }, payload: { ...base, iss: "https://evil.example.com" } },
  { header: { alg: "RS256", kid: "k1" }, payload: { ...base, aud: "analytics-dashboard" } },
  { header: { alg: "RS256", kid: "k1" }, payload: { ...base, exp: NOW - 400 } },
  { header: { alg: "RS256", kid: "k1" }, payload: { ...base, exp: NOW - 100, nonce: "n-bad" } },
  { header: { alg: "ES256", kid: "k2" }, payload: { ...base } },
];

const out = tokens.map((t, i) => `t${i + 1}: ${validate(t)}`);
console.log(out.join("\n"));
